module grid_computation (input clk, input rst_n, input start, input [3:0] x, input [3:0] y, output reg [31:0] result, output reg done); reg [31:0] current_row [0:15]; reg [31:0] prev_row [0:15]; reg [31:0] prev_prev_row [0:15]; reg [3:0] i, j; reg [31:0] result_reg; reg done_reg; reg [3:0] state; always @(posedge clk or negedge rst_n) begin if (!rst_n) begin state <= 3'd0; i <= 0; j <= 0; done_reg <= 0; result_reg <= 0; current_row <= 0; prev_row <= 0; prev_prev_row <= 0; end else begin if (state == 3'd0) begin if (start) begin state <= 3'd1; i <= 0; j <= 0; end end else if (state == 3'd1) begin if (i >= 16) begin done_reg <= 1; state <= 3'd3; end else begin if (j < 16) begin state <= 3'd2; end else begin i <= i + 1; j <= 0; prev_prev_row <= prev_row; prev_row <= current_row; current_row <= 0; if (i < 16) begin state <= 3'd1; end else begin done_reg <= 1; state <= 3'd3; end end end end end else if (state == 3'd2) begin int val; if (i == 0) begin if (j == 0) val = 0; else if (j == 1) val = 1; else begin val = current_row[j-1] + current_row[j-2]; if (val >= 1000000007) val -= 1000000007; end end else if (i == 1) begin if (j == 0) val = 1; else begin val = prev_row[j] + current_row[j-1]; if (val >= 1000000007) val -= 1000000007; end end else begin if (j == 0) begin val = prev_row[0] + prev_prev_row[0]; if (val >= 1000000007) val -= 1000000007; end else begin val = prev_row[j] + current_row[j-1]; if (val >= 1000000007) val -= 1000000007; end end end current_row[j] <= val; if (i == x && j == y) begin result_reg <= val; end j <= j + 1; state <= 3'd1; end else if (state == 3'd3) begin state <= 3'd3; end end end assign result = result_reg; assign done = done_reg; endmodule